// The tab icon, and the installed app's icon (hub /app-icon.svg): transparent, dark ink, light ink on a dark tab bar.
const ICON_INK = "#343a40";
const DOTS: Record<string, string> = { waiting: "#e03131", working: "#f59f00", unseen: "#1c7ed6" };
// states: any of waiting/working/unseen, each drawn once, most urgent first.
// The icon alone, centred in a 32 box.
function glyph(name: string) {
 const [box, d, evenodd] = ICONS[name], [, , w, h] = box.split(" ").map(Number), scale = 32 / Math.max(w, h);
 return `<path transform="translate(${(16 - w * scale / 2).toFixed(2)} ${(16 - h * scale / 2).toFixed(2)}) scale(${scale.toFixed(4)})" fill="${ICON_INK}"${evenodd ? ' fill-rule="evenodd"' : ""} d="${d}"/>`;
}
const SVG_HEAD = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><style>@media (prefers-color-scheme: dark) { path { fill: #e9ecef } }</style>';
export function iconSvg(name: string, states: string[] = [], r = 6.5) {
 // At 16 px an outline reads as noise: the icon keeps the whole square and white-ringed dots (Gmail/Slack style) carry the states,
 // filling lower-right, lower-left, then upper-right; two fit side by side at 16 px. r: dot radius in the 32 box.
 const near = r + 1, far = 32 - near;
 const badge = Object.keys(DOTS).filter(state => states.includes(state)).map((state, i) => `<circle cx="${i === 1 ? near : far}" cy="${i === 2 ? near : far}" r="${r}" fill="${DOTS[state]}" stroke="#fff" stroke-width="2"/>`).join("");
 return `${SVG_HEAD}${glyph(name)}${badge}</svg>`;
}
// The desktop app's taskbar icon: one cell per hub (1 = whole square, 2 side by side, 3-4 in 2x2; more show only as app tabs).
// One hub: bigger dots. Two: the dots sit in the empty strips, waiting and working below the icon, unseen above, so they hide nothing.
// Three or four: a dot matrix, see below.
export function hubsIconSvg(hubs: { icon: string; states: string[] }[]) {
 hubs = hubs.filter(hub => ICONS[hub.icon]).slice(0, 4);
 if (hubs.length < 2) return iconSvg(hubs[0]?.icon ?? Object.keys(ICONS)[0], hubs[0]?.states, 7);
 // Two or more: icons are mush at 24 px, so a matrix of dots only: one column per hub (left to right like the tabs),
 // one row per state (waiting, working, unseen); a faint ring marks an off state so each column stays visible.
 // Two hubs take the outer columns of three, leaving the middle one empty.
 const slots = hubs.length === 2 ? 3 : hubs.length, column = 32 / slots, r = Math.min(4.6, column / 2 - 0.6);
 return SVG_HEAD + hubs.map((hub, index) => ["waiting", "working", "unseen"].map((state, j) => {
  const i = hubs.length === 2 ? index * 2 : index, at = `cx="${(column * i + column / 2).toFixed(2)}" cy="${5.5 + j * 10.5}"`;
  return hub.states.includes(state) ? `<circle ${at} r="${r.toFixed(2)}" fill="${DOTS[state]}"/>` : `<circle ${at} r="${(r - 0.5).toFixed(2)}" fill="none" stroke="${ICON_INK}" stroke-opacity=".35"/>`;
 }).join("")).join("") + "</svg>";
}

